import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#7
it('releases a partially initialized session before rejecting its original error', async () => {
  const session: ChatSession = {sessionId: 'partial', userId: 'user', entries: []};
  const resources = new Set<ChatSession>();
  const failure = new Error('initialization failed');
  const errors: unknown[] = [];
  const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'Assistant'}), undefined, {
    hooks: {
      beforeSession: async current => {
        resources.add(current);
        throw failure;
      },
      onError: async (current, error) => {
        errors.push([current === session, error === failure]);
      },
      afterSession: async current => {
        resources.delete(current);
      },
    },
  });

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({released: resources.size === 0, errors, originalError: rejection === failure}).toEqual({
    released: true,
    errors: [[true, true]],
    originalError: true,
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/chatOrchestrator.initialization.test.ts --runInBand"
